import Page from "../Page/Page";
import "./HomePage.css";
import Card from "../../Components/CardContainer/Card";
import * as userService from "../../Services/UserService";
import { useState } from "react";

const HomePage = () => {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [otpCode, setOtpCode] = useState("");

  const handleLogin = async () => {
    try {
      const response = await userService.loginUser({ email, password });
      alert(response); // "OTP sent"
    } catch (error) {
      console.error("Login failed");
    }
  };

  const handleVerifyOtp = async () => {
    try {
      const response = await userService.verifyOtp({ email, otpCode });
      alert(response); // "OTP verified successfully"
    } catch (error) {
      console.error("OTP verification failed");
    }
  };

  return (
    <Page>
      <div className="home-page-heading-container">
        <h1>Look for sports coaches online!</h1>
        <p>Sign up for training from the comfort of your home</p>
        {/* <input type="text" placeholder="Enter the lastname or " /> */}

        <div>
          <input
            placeholder="Email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
          />
          <input
            placeholder="Password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
          />
          <button onClick={handleLogin}>Увійти</button>
        </div>
        <div>
          <input
            placeholder="Otp"
            value={otpCode}
            onChange={(e) => setOtpCode(e.target.value)}
          />
          <button onClick={handleVerifyOtp}>Підтвердити код</button>
        </div>
      </div>
    </Page>
  );
};

export default HomePage;
